import React, { useState, useEffect, useCallback } from 'react';
import Particles, { initParticlesEngine } from "@tsparticles/react";
import { loadSlim } from "@tsparticles/slim";
import * as faceapi from 'face-api.js';
import Navigation from './components/Navigation/Navigation.js';
import Signin from './components/SignIn/Signin.js';
import Register from './components/Register/Register.js';
import FaceRecognition from './components/FaceRecognition/FaceRecognition.js';
import Logo from './components/Logo/Logo.js';
import ImageLinkForm from './components/ImageLinkForm/ImageLinkForm.js';
import Rank from './components/Rank/Rank.js';
import './App.css';

const particleOptions = {
  particles: {
    number: {
      value: 40,
      density: { enable: true, area: 900 }
    },
    color: { value: '#8b5cf6' },
    links: {
      enable: true,
      color: '#8b5cf6',
      opacity: 0.08,
      distance: 150
    },
    move: {
      enable: true,
      speed: 0.6,
      direction: "none",
      outModes: { default: "bounce" }
    },
    opacity: { value: 0.15 },
    size: { value: { min: 1, max: 2 } }
  },
  interactivity: {
    events: {
      onHover: { enable: true, mode: "grab" },
    },
    modes: {
      grab: { distance: 140, links: { opacity: 0.2 } }
    }
  }
};

const App = () => {
  const [input, setInput] = useState('');
  const [imageUrl, setImageUrl] = useState('');
  const [box, setBox] = useState({});
  const [route, setRoute] = useState('signin');
  const [isSignedIn, setIsSignedIn] = useState(false);
  const [particlesInit, setParticlesInit] = useState(false);
  const [modelsLoaded, setModelsLoaded] = useState(false);
  const [detecting, setDetecting] = useState(false);

  useEffect(() => {
    // Init particles
    initParticlesEngine(async (engine) => {
      await loadSlim(engine);
    }).then(() => setParticlesInit(true));

    // Load face detection model
    faceapi.nets.tinyFaceDetector.loadFromUri('/facerecognitionbrain/models')
      .then(() => {
        console.log('✅ Face detection model loaded');
        setModelsLoaded(true);
      })
      .catch(err => console.log('Model load error:', err));
  }, []);

  const detectFace = useCallback(async () => {
    const image = document.getElementById('inputimage');
    if (!image || !modelsLoaded) return;

    setDetecting(true);

    try {
      const detection = await faceapi.detectSingleFace(
        image,
        new faceapi.TinyFaceDetectorOptions()
      );

      if (detection) {
        const displaySize = { width: image.width, height: image.height };
        const resizedDetection = faceapi.resizeResults(detection, displaySize);
        const b = resizedDetection.box;
        setBox({
          leftCol: b.x,
          topRow: b.y,
          rightCol: image.width - (b.x + b.width),
          bottomRow: image.height - (b.y + b.height)
        });
      } else {
        setBox({});
      }
    } catch (err) {
      console.log('Detection error:', err);
    }

    setDetecting(false);
  }, [modelsLoaded]);

  const onInputChange = (event) => {
    setInput(event.target.value);
  };

  const onButtonSubmit = () => {
    if (!input) return;
    setBox({});
    setDetecting(true);

    // Fetch image as blob to avoid cross-origin tainted canvas
    fetch(input)
      .then(res => res.blob())
      .then(blob => {
        const reader = new FileReader();
        reader.onloadend = () => {
          setImageUrl(reader.result);
          setDetecting(false);
        };
        reader.readAsDataURL(blob);
      })
      .catch(() => {
        // Fallback: use the URL directly (CORS-enabled servers)
        setImageUrl(input);
        setDetecting(false);
      });
  };

  const onFileChange = (event) => {
    const file = event.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => {
      setImageUrl(reader.result);
      setBox({});
    };
    reader.readAsDataURL(file);
  };

  const onImageLoaded = () => {
    detectFace();
  };

  const onRouteChange = (route) => {
    if (route === 'signout') {
      setIsSignedIn(false);
      setImageUrl('');
      setBox({});
    } else if (route === 'home') {
      setIsSignedIn(true);
    }
    setRoute(route);
  };

  return (
    <div className="App">
      {particlesInit && (
        <Particles id="tsparticles" className='particles' options={particleOptions} />
      )}
      <Navigation isSignedIn={isSignedIn} onRouteChange={onRouteChange} />
      {route === 'home'
        ? <div className='main-content'>
            <Logo />
            <Rank />
            {!modelsLoaded && (
              <div className='models-loading'>
                <div className='models-loading-bar'></div>
                <span className='models-loading-text'>Loading AI model...</span>
              </div>
            )}
            <ImageLinkForm
              onInputChange={onInputChange}
              onButtonSubmit={onButtonSubmit}
              onFileChange={onFileChange}
            />
            {detecting && (
              <div className='detecting-indicator'>
                <div className='detecting-spinner'></div>
                <span className='detecting-text'>Analyzing face...</span>
              </div>
            )}
            <FaceRecognition box={box} imageUrl={imageUrl} onImageLoaded={onImageLoaded} />
          </div>
        : (
            route === 'signin'
            ? <Signin onRouteChange={onRouteChange} />
            : <Register onRouteChange={onRouteChange} />
          )
      }
    </div>
  );
};

export default App;
